<template>
  <div class="order-management">
    <!-- 页面标题与操作按钮 -->
    <div class="header">
      <h2>订单管理</h2>
      <el-button type="primary" @click="handleAdd">+ 新增订单</el-button>
    </div>

    <!-- 搜索与筛选区域 -->
    <el-card class="filter-card" shadow="never">
      <el-form :inline="true" :model="searchForm" size="small">
        <el-form-item label="订单号">
          <el-input v-model="searchForm.orderNo" placeholder="请输入" clearable />
        </el-form-item>
        <el-form-item label="客户名称">
          <el-input v-model="searchForm.customerName" placeholder="请输入" clearable />
        </el-form-item>
        <el-form-item label="订单状态">
          <el-select v-model="statusFilter" placeholder="全部" clearable style="width: 140px">
            <el-option label="待付款" value="pending" />
            <el-option label="已付款" value="paid" />
            <el-option label="已发货" value="shipped" />
            <el-option label="已完成" value="completed" />
            <el-option label="已取消" value="cancelled" />
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="handleSearch">查询</el-button>
          <el-button @click="resetSearch">重置</el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <!-- 订单列表表格 -->
    <el-card class="table-card" shadow="never">
      <el-table :data="paginatedData" border stripe style="width: 100%">
        <el-table-column prop="orderNo" label="订单号" width="180" />
        <el-table-column prop="customerName" label="客户名称" min-width="120" />
        <el-table-column prop="totalAmount" label="订单金额" width="120">
          <template v-slot:default="scope">
            ¥ {{ scope.row.totalAmount.toFixed(2) }}
          </template>
        </el-table-column>
        <el-table-column prop="status" label="状态" width="100">
          <template v-slot:default="scope">
            <el-tag :type="statusTagType(scope.row.status)" size="small">
              {{ statusText(scope.row.status) }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="createTime" label="下单时间" width="160" />
        <el-table-column label="操作" width="200" fixed="right">
          <template v-slot:default="scope">
            <el-button type="text" size="small" @click="handleEdit(scope.row)">编辑</el-button>
            <el-button type="text" size="small" @click="handleView(scope.row)">详情</el-button>
            <el-button type="text" size="small" style="color: #f56c6c" @click="handleDelete(scope.row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>

      <!-- 分页组件 -->
      <el-pagination
        class="pagination"
        @current-change="handlePageChange"
        @size-change="handleSizeChange"
        :current-page="currentPage"
        :page-sizes="[10, 20, 50, 100]"
        :page-size="pageSize"
        layout="total, sizes, prev, pager, next, jumper"
        :total="filteredData.length"
      />
    </el-card>

    <!-- 新增/编辑订单对话框 -->
    <el-dialog
      :title="dialogType === 'add' ? '新增订单' : '编辑订单'"
      v-model:visible="dialogVisible"
      width="500px"
      @close="resetForm"
    >
      <el-form ref="orderForm" :model="currentOrder" :rules="formRules" label-width="100px">
        <el-form-item label="订单号" prop="orderNo">
          <el-input v-model="currentOrder.orderNo" placeholder="请输入订单号" :disabled="dialogType === 'edit'" />
        </el-form-item>
        <el-form-item label="客户名称" prop="customerName">
          <el-input v-model="currentOrder.customerName" placeholder="请输入客户名称" />
        </el-form-item>
        <el-form-item label="订单金额" prop="totalAmount">
          <el-input-number v-model="currentOrder.totalAmount" :precision="2" :min="0" style="width: 100%" />
        </el-form-item>
        <el-form-item label="订单状态" prop="status">
          <el-select v-model="currentOrder.status" placeholder="请选择" style="width: 100%">
            <el-option label="待付款" value="pending" />
            <el-option label="已付款" value="paid" />
            <el-option label="已发货" value="shipped" />
            <el-option label="已完成" value="completed" />
            <el-option label="已取消" value="cancelled" />
          </el-select>
        </el-form-item>
      </el-form>
      <template v-slot:footer>
        <span class="dialog-footer">
          <el-button @click="dialogVisible = false">取 消</el-button>
          <el-button type="primary" @click="saveOrder">确 定</el-button>
        </span>
      </template>
    </el-dialog>

    <!-- 查看详情对话框 -->
    <el-dialog title="订单详情" v-model:visible="detailVisible" width="500px">
      <el-descriptions :column="1" border>
        <el-descriptions-item label="订单号">{{ viewOrder.orderNo }}</el-descriptions-item>
        <el-descriptions-item label="客户名称">{{ viewOrder.customerName }}</el-descriptions-item>
        <el-descriptions-item label="订单金额">¥ {{ viewOrder.totalAmount?.toFixed(2) }}</el-descriptions-item>
        <el-descriptions-item label="订单状态">
          <el-tag :type="statusTagType(viewOrder.status)">{{ statusText(viewOrder.status) }}</el-tag>
        </el-descriptions-item>
        <el-descriptions-item label="下单时间">{{ viewOrder.createTime }}</el-descriptions-item>
      </el-descriptions>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'OrderManagement',
  data() {
    return {
      // 模拟订单数据
      allOrders: [
        {
          id: 1,
          orderNo: 'ORD20240115001',
          customerName: '深圳科技有限公司',
          totalAmount: 12500.00,
          status: 'paid',
          createTime: '2024-01-15 10:30'
        },
        {
          id: 2,
          orderNo: 'ORD20240220002',
          customerName: '上海贸易有限公司',
          totalAmount: 8900.50,
          status: 'shipped',
          createTime: '2024-02-20 14:20'
        },
        {
          id: 3,
          orderNo: 'ORD20240310003',
          customerName: '北京咨询服务有限公司',
          totalAmount: 3500.00,
          status: 'pending',
          createTime: '2024-03-10 09:15'
        }
      ],
      searchForm: {
        orderNo: '',
        customerName: ''
      },
      statusFilter: '',
      currentPage: 1,
      pageSize: 10,
      dialogVisible: false,
      dialogType: 'add',
      currentOrder: this.getEmptyOrder(),
      detailVisible: false,
      viewOrder: {},
      formRules: {
        orderNo: [{ required: true, message: '请输入订单号', trigger: 'blur' }],
        customerName: [{ required: true, message: '请输入客户名称', trigger: 'blur' }],
        totalAmount: [{ required: true, message: '请输入订单金额', trigger: 'blur' }],
        status: [{ required: true, message: '请选择订单状态', trigger: 'change' }]
      }
    }
  },
  computed: {
    filteredData() {
      return this.allOrders.filter(item => {
        const matchOrderNo = !this.searchForm.orderNo || item.orderNo.includes(this.searchForm.orderNo)
        const matchCustomer = !this.searchForm.customerName || item.customerName.includes(this.searchForm.customerName)
        const matchStatus = !this.statusFilter || item.status === this.statusFilter
        return matchOrderNo && matchCustomer && matchStatus
      })
    },
    paginatedData() {
      const start = (this.currentPage - 1) * this.pageSize
      const end = start + this.pageSize
      return this.filteredData.slice(start, end)
    }
  },
  methods: {
    getEmptyOrder() {
      return {
        id: null,
        orderNo: '',
        customerName: '',
        totalAmount: 0,
        status: 'pending',
        createTime: ''
      }
    },
    statusText(status) {
      const map = {
        pending: '待付款',
        paid: '已付款',
        shipped: '已发货',
        completed: '已完成',
        cancelled: '已取消'
      }
      return map[status] || status
    },
    statusTagType(status) {
      const map = {
        pending: 'warning',
        paid: 'success',
        shipped: 'primary',
        completed: 'info',
        cancelled: 'danger'
      }
      return map[status] || 'info'
    },
    handleSearch() {
      this.currentPage = 1
    },
    resetSearch() {
      this.searchForm = { orderNo: '', customerName: '' }
      this.statusFilter = ''
      this.currentPage = 1
    },
    handleAdd() {
      this.dialogType = 'add'
      this.currentOrder = this.getEmptyOrder()
      this.dialogVisible = true
    },
    handleEdit(row) {
      this.dialogType = 'edit'
      this.currentOrder = { ...row }
      this.dialogVisible = true
    },
    handleView(row) {
      this.viewOrder = { ...row }
      this.detailVisible = true
    },
    handleDelete(row) {
      this.$confirm(`确认删除订单“${row.orderNo}”吗？`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        const index = this.allOrders.findIndex(o => o.id === row.id)
        if (index !== -1) {
          this.allOrders.splice(index, 1)
          if (this.paginatedData.length === 0 && this.currentPage > 1) {
            this.currentPage--
          }
        }
        this.$message.success('删除成功')
      }).catch(() => {})
    },
    saveOrder() {
      this.$refs.orderForm.validate(valid => {
        if (valid) {
          if (this.dialogType === 'add') {
            const newId = Math.max(...this.allOrders.map(o => o.id), 0) + 1
            const now = new Date()
            const createTime = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`
            const newOrder = {
              ...this.currentOrder,
              id: newId,
              createTime
            }
            this.allOrders.push(newOrder)
            this.$message.success('新增成功')
          } else {
            const index = this.allOrders.findIndex(o => o.id === this.currentOrder.id)
            if (index !== -1) {
              this.allOrders[index] = { ...this.currentOrder, createTime: this.allOrders[index].createTime }
            }
            this.$message.success('编辑成功')
          }
          this.dialogVisible = false
        }
      })
    },
    resetForm() {
      this.$refs.orderForm?.clearValidate()
      this.currentOrder = this.getEmptyOrder()
    },
    handlePageChange(page) {
      this.currentPage = page
    },
    handleSizeChange(size) {
      this.pageSize = size
      this.currentPage = 1
    }
  }
}
</script>

<style scoped>
.order-management {
  padding: 20px;
}
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}
.filter-card {
  margin-bottom: 20px;
}
.table-card {
  margin-bottom: 20px;
}
.pagination {
  margin-top: 20px;
  text-align: right;
}
</style>